@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h3>Notepad</h3>

<textarea class="form-control mb-3" rows="10" @bind="content" @bind:event="oninput"></textarea>

<div class="d-flex align-items-center gap-3 mb-3">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-danger" @onclick="Clear">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSavedAt;
    private System.Threading.Timer? autoSaveTimer;
    private IJSObjectReference? module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>("import", "./Components/Pages/Notepad.razor.js");

            var restored = await module.InvokeAsync<string?>("load");
            if (restored is not null)
            {
                content = restored;
                savedContent = restored;
                StateHasChanged();
            }

            await module.InvokeVoidAsync("registerBeforeUnload");

            autoSaveTimer = new System.Threading.Timer(async _ =>
            {
                await InvokeAsync(async () =>
                {
                    if (content != savedContent)
                    {
                        await Save();
                        StateHasChanged();
                    }
                });
            }, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    private async Task SaveNow()
    {
        await Save();
    }

    private async Task Save()
    {
        if (module is null) return;
        await module.InvokeVoidAsync("save", content);
        savedContent = content;
        lastSavedAt = DateTime.Now;
        await module.InvokeVoidAsync("setDirty", false);
    }

    private async Task Clear()
    {
        if (module is null) return;
        content = string.Empty;
        savedContent = string.Empty;
        lastSavedAt = null;
        await module.InvokeVoidAsync("clear");
        await module.InvokeVoidAsync("setDirty", false);
    }

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
        {
            await autoSaveTimer.DisposeAsync();
        }
        if (module is not null)
        {
            await module.InvokeVoidAsync("unregisterBeforeUnload");
            await module.DisposeAsync();
        }
    }
}

const STORAGE_KEY = "notepad-content";

let beforeUnloadHandler = null;
let dirty = false;

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY);
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
}

export function setDirty(value) {
    dirty = value;
}

export function registerBeforeUnload() {
    beforeUnloadHandler = (e) => {
        if (dirty) {
            e.preventDefault();
        }
    };

    // Track input changes to set dirty flag
    document.addEventListener("input", onInput);
    window.addEventListener("beforeunload", beforeUnloadHandler);
}

export function unregisterBeforeUnload() {
    if (beforeUnloadHandler) {
        window.removeEventListener("beforeunload", beforeUnloadHandler);
        beforeUnloadHandler = null;
    }
    document.removeEventListener("input", onInput);
}

function onInput(e) {
    if (e.target && e.target.tagName === "TEXTAREA") {
        dirty = true;
    }
}

